begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
set local test.fms.defer_start='true';
set local test.fms.call_mode='manual_handoff';
\ir helpers/fms_visit_assignment_fixture.psql
create temporary table initial_handoff(request jsonb,preview jsonb,handoffs jsonb,key uuid,result jsonb);
grant all on initial_handoff to authenticated;
insert into initial_handoff(request,key,handoffs) values(jsonb_build_object('kind','starter_form','starterAssignmentId',(select id from visit_assignment_fixture where name='starter'),'formTemplateId',(select id from visit_assignment_fixture where name='form'),'answers',jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='b'))),gen_random_uuid(),jsonb_build_array(jsonb_build_object('targetStageId',(select id from visit_assignment_fixture where name='call'),'userProfileId',(select id from visit_assignment_fixture where name='d'))));
update initial_handoff set preview=preview_fms_work_transition(request);
select is((select preview#>>'{destinations,0,effectiveUserId}' from initial_handoff),null,'manual first work has no invented default employee');
select is((select preview#>>'{destinations,0,allowHandoff}' from initial_handoff),'true','starting form offers an authorized handoff before creating work');
select is((select count(*)::integer from fms_instances where fms_flow_id=(select id from visit_assignment_fixture where name='flow')),0,'starting preview creates no placeholder instance');
select throws_ok($$select transition_fms_work_with_audit(request,gen_random_uuid(),'[]',preview->>'fingerprint') from initial_handoff$$,'23514',null,'first manual owner is required atomically');
select is((select count(*)::integer from form_submissions where form_template_id=(select id from visit_assignment_fixture where name='form')),0,'missing first owner leaves the starting form unsaved');
update initial_handoff set preview=preview_fms_work_transition(request,handoffs);
select is((select preview#>>'{destinations,0,effectiveUserId}' from initial_handoff),(select id::text from visit_assignment_fixture where name='d'),'confirmed initial choice is previewed');
update initial_handoff set result=transition_fms_work_with_audit(request,key,handoffs,preview->>'fingerprint');
select is((select result->>'state' from initial_handoff),'successors_activated','one final transaction starts the manual first work');
select is((select work.assigned_to from fms_instance_stages work where work.fms_stage_id=(select id from visit_assignment_fixture where name='call')),array[(select id from visit_assignment_fixture where name='d')],'actual first employee matches the confirmed preview');
select is((select jsonb_array_length(result->'ownWorkTargets') from initial_handoff),0,'starter is not sent into another employee work');
select is((select result->>'workflowName' from initial_handoff),'Jewellery enquiry','starting confirmation names the actual workflow');
select is((select transition_fms_work_with_audit(request,key,handoffs,preview->>'fingerprint') from initial_handoff),(select result from initial_handoff),'lost starting response can be retried without another instance');
select is((select status from fms_starter_assignments where id=(select id from visit_assignment_fixture where name='starter')),'completed','the exact starter assignment closes after successful start');
reset role;
select is((select count(*)::integer from fms_stage_assignment_decisions decision join fms_instance_stages work on work.id=decision.target_instance_stage_id where work.fms_stage_id=(select id from visit_assignment_fixture where name='call') and decision.source_submission_id is not null),1,'initial manual choice records its real source submission and visit');
select * from finish();
rollback;
